import json
from pathlib import Path
p=Path(__file__).with_name('editorial.json');d=json.loads(p.read_text())
def add(lid,prompt,options,correct,why,objectives,type='multiple',**extra):
 d['questions'][lid].append(dict(type=type,prompt=prompt,options=options,correct=correct,explanation=why,objectiveIds=objectives,difficulty='avanzado',**extra))
add('l29','Selecciona tres artefactos que deben versionarse para reproducir una regresión de un agente.',[['Código de integración','Define lógica y manejo de errores.'],['Esquemas de herramientas','Cambian qué argumentos son aceptados.'],['Configuración de evaluación','Define casos y criterios de aceptación.'],['Token temporal de acceso','Es un secreto temporal, no se guarda en el repositorio.']],[0,1,2],'Versiona contratos y configuración, sin persistir credenciales temporales.',['p08'])
add('l30','Selecciona dos medidas apropiadas ante un límite temporal de consumo.',[['Backoff con reintentos acotados','Reduce presión y limita amplificación.'],['Reducir contexto redundante evaluando calidad','Puede bajar demanda conservando evidencia suficiente.'],['Reintentar sin espera y sin límite','Puede agravar saturación.'],['Más réplicas del frontend como única solución','No elimina la cuota del modelo.']],[0,1],'La reducción de demanda y reintentos acotados deben respetar calidad y tiempo total.',['p09'])
add('l37','Una respuesta tiene JSON válido y citas presentes. Selecciona tres comprobaciones aún necesarias.',[['Respaldo de cada afirmación','Una cita no demuestra todos los hechos.'],['Relevancia a la pregunta','Una respuesta puede ser válida pero no atender la consulta.'],['Seguridad y autorización de acciones','La estructura no garantiza permisos ni política.'],['Que el texto sea siempre el más extenso','Longitud no es un criterio universal de calidad.']],[0,1,2],'Formato, respaldo, relevancia y acciones autorizadas son dimensiones distintas.',['g04','p14'])
add('l49','Selecciona tres metadatos útiles para una ingesta documental autorizada y actualizable.',[['Identificador de fuente','Permite relacionar actualizaciones y borrados.'],['Versión o fecha de vigencia','Ayuda a detectar evidencia obsoleta.'],['Alcance de acceso','Permite limitar recuperación por usuario.'],['Clave privada en cada fragmento','Expone un secreto y no es un permiso documental.']],[0,1,2],'Una fuente indexada debe mantener identidad, vigencia y permisos sin copiar secretos.',['x01','x04'])
add('l33','Una imagen contiene instrucciones hostiles. Selecciona tres controles complementarios.',[['Tratar OCR como datos externos','No eleva texto extraído a política.'],['Validar herramientas y destinos','Limita efectos de una instrucción maliciosa.'],['Detección de ataque y revisión','Aporta señales que requieren políticas de respuesta.'],['Aceptar el texto como orden de sistema','Introduce la vulnerabilidad.']],[0,1,2],'Separación de confianza, detección y límites de ejecución trabajan en capas.',['v15','p13'])
add('l48','Un agente de voz realiza operaciones sensibles. Selecciona tres pruebas pertinentes.',[['Interrupción y corrección de turno','Permite cambiar una intención antes del efecto.'],['Confirmación de identificadores','Reduce riesgo por error de reconocimiento.'],['Aprobación específica de la operación','Controla efectos autorizados.'],['Sólo naturalidad de la voz sintetizada','No comprueba reconocimiento ni autorización.']],[0,1,2],'La interacción útil evalúa turnos, datos críticos y autorización, además de voz.',['t05','t06','g11'])
add('l43','Antes de generar y editar vídeos con un servicio, selecciona dos verificaciones necesarias.',[['Modalidades y operaciones del modelo','No todos aceptan referencias o extensión.'],['Controles y límites de la versión','Duración, resolución y edición dependen del contrato.'],['Que cualquier modelo de imágenes sirva','No demuestra soporte de vídeo.'],['Que un prompt largo habilite operaciones','Las instrucciones no crean capacidades de API.']],[0,1],'La implementación necesita capacidades y controles documentados del modelo y versión.',['v02','v04','v05'])
add('l45','Selecciona dos condiciones que debes comprobar para elegir una canalización avanzada de documentos.',[['Versión y estado GA o preview','Determinan contrato y condiciones.'],['Modalidad y tipos de campo admitidos','Las capacidades no son universales.'],['Que la palabra pro implique toda modalidad','Extrapola documentación histórica.'],['Que nunca necesite revisión humana','No está garantizado por el analizador.']],[0,1],'Relaciona el término del temario con las capacidades de la API vigente.',['v12','x08'])
add('l38','Lee: AIProjectClient(endpoint=os.environ["FOUNDRY_PROJECT_ENDPOINT"], credential=DefaultAzureCredential()). ¿Qué depende aún del entorno?',[['Endpoint configurado, identidad y permisos','El constructor no crea recursos ni concede acceso.'],['Únicamente el número de tokens','Antes hay requisitos de conexión y autorización.'],['Nada; el cliente concede rol automáticamente','La credencial no asigna roles.'],['Sólo una key embebida en el código','El ejemplo usa credencial, no necesita exponer una key.']],[0],'El ejemplo requiere configuración y un principal autorizado; no ejecuta inferencia.',['g05','g06'],type='single')
add('l38','En el ejemplo Python, ¿qué hace el bloque with DefaultAzureCredential() as identity?',[['Gestiona el ciclo de vida del proveedor de credencial','Su contexto se cierra al salir del bloque.'],['Concede rol de propietario de Azure','El proveedor no asigna permisos.'],['Crea un proyecto de producción','No es una operación de creación de recurso.'],['Ejecuta un prompt en el navegador','NexoCert no es un intérprete Python.']],[0],'El contexto gestiona recursos del cliente de credenciales; autorización se configura aparte.',['g05','g06'],type='single')
add('l36','La arquitectura del diagrama entrega todos los documentos al modelo antes de filtrar al usuario. ¿Qué corrección priorizas?',[['Filtrar evidencia autorizada antes de construir contexto','Evita exponer datos al modelo que el usuario no puede consultar.'],['Filtrar sólo la respuesta final','La evidencia ya fue expuesta al contexto.'],['Añadir una cita por documento','Procedencia no concede permiso.'],['Aumentar el máximo de salida','No corrige autorización documental.']],[0],'La autorización de retrieval debe preservar la frontera de datos antes de generar.',['g02','x02','p12'],type='single',diagram={'nodes':['Usuario','Índice completo','Modelo','Filtro tardío'],'description':'Flujo incorrecto: la evidencia sin filtro llega al modelo; el filtro se aplica después.'})
add('l39','El coordinador recibe un error del recuperador y un análisis sin fuente. ¿Qué impide elevar una conclusión a hecho?',[['Contrato que propaga fallo y exige evidencia','El validador no puede aceptar respaldo inexistente.'],['Mayor longitud del informe','No crea evidencia.'],['Votación entre agentes sin referencias','Pueden compartir el mismo error.'],['Ocultar el error al validador','Hace imposible controlar el resultado.']],[0],'El flujo conserva fallos y procedencia; el validador debe rechazar resultados no respaldados.',['g10','g12'],type='single',diagram={'nodes':['Coordinador','Recuperador: fallo','Analista: propuesta','Validador'],'description':'Dos resultados llegan al validador: falta evidencia y existe sólo una propuesta.'})
p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print('Añadidas 12 preguntas de selección múltiple, código y arquitectura.')
d['questions']['l16'][1]['objectiveIds']=['v09']
add('l44','Una detección identifica un componente visual que debe revisarse. ¿Qué salida permite ubicar la evidencia?',[['Clase, región y referencia a la imagen','Permite localizar el componente y comprobar la detección.'],['Sólo categoría global de la escena','No identifica la ubicación del componente.'],['Un caption general sin localización','Puede describir sin señalar la región concreta.'],['Sólo un vector del contenido completo','No expone por sí solo región verificable del objeto.']],[0],'Para revisar objetos y componentes necesitas localización y procedencia, no sólo una descripción global.',['v13'],type='single')
p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
